$ErrorActionPreference = 'Stop'
if (-not (Test-Path 'package.json')) {
    Write-Host 'ERROR: run from project root.' -ForegroundColor Red
    exit 1
}

Write-Host '-> Installing dnd-kit (drag-and-drop library)' -ForegroundColor Cyan
npm install @dnd-kit/core @dnd-kit/sortable @dnd-kit/utilities --silent
Write-Host '  done' -ForegroundColor Green

$files = @{}
$files['lib/db/deals.ts'] = ''
$files['app/(app)/deals/actions.ts'] = ''
$files['app/(app)/deals/page.tsx'] = ''
$files['app/(app)/deals/_components/pipeline-kanban.tsx'] = ''
$files['app/(app)/deals/_components/kanban-column.tsx'] = ''
$files['app/(app)/deals/_components/deal-card.tsx'] = ''
$files['app/(app)/deals/new/page.tsx'] = ''
$files['app/(app)/deals/_components/deal-form.tsx'] = ''
$files['app/(app)/deals/[id]/page.tsx'] = ''
$files['app/(app)/deals/[id]/edit/page.tsx'] = ''
$files['app/(app)/deals/_components/stage-selector.tsx'] = ''
$files['lib/db/activities.ts'] = ''
$files['app/(app)/activities/actions.ts'] = ''
$files['components/app/activity-log-panel.tsx'] = ''
$files['components/app/activity-timeline.tsx'] = ''
$files['app/(app)/activities/page.tsx'] = ''
$files['app/(app)/activities/_components/activities-list.tsx'] = ''
$files['app/(app)/accounts/[id]/page.tsx'] = ''
$files['app/(app)/contacts/[id]/page.tsx'] = ''
$files['app/(app)/dashboard/page.tsx'] = ''

Write-Host ''
Write-Host '-> Day 4 code drop' -ForegroundColor Cyan
foreach ($path in $files.Keys) {
    $content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($files[$path]))
    $dir = Split-Path -Parent $path
    if ($dir -and -not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    $fullPath = Join-Path -Path (Get-Location) -ChildPath $path
    [System.IO.File]::WriteAllText($fullPath, $content, [System.Text.UTF8Encoding]::new($false))
    Write-Host ('  + ' + $path) -ForegroundColor Green
}

Write-Host ''
Write-Host '====================================' -ForegroundColor Green
Write-Host '  Day 4 files written' -ForegroundColor Green
Write-Host '====================================' -ForegroundColor Green
Write-Host ''
Write-Host 'Test: npm run dev  ->  http://localhost:3000/deals' -ForegroundColor Cyan
